const books=['Genesis','Exodus','Leviticus','Numbers','Deuteronomy','Joshua','Judges','Ruth','1 Samuel','2 Samuel','1 Kings','2 Kings','Psalms','Isaiah','Matthew','John','Romans','Hebrews','James','Revelation'];
const topics=[['Covenant','Promise, obligation, identity, and belonging across Scripture.'],['Kingdom of God','Rule, hope, justice, and the proclamation of Jesus.'],['Grace','Gift, restoration, salvation, and life with God.'],['Law & Torah','Instruction, covenant identity, ethics, and interpretation.'],['Justice','Righteousness, power, the vulnerable, judgment, and restoration.'],['Messiah','Anointed figures, expectation, Jesus, and Christian interpretation.'],['Resurrection','Israel’s hopes, Jesus’ resurrection, and new creation.'],['Holy Spirit','Presence, empowerment, gifts, fruit, and community.']];
const lessons=[['1.1','Why the Bible Matters','complete'],['1.2','The Story and Its Setting','current'],['1.3','The World of the Bible','locked'],['1.4','People, Places, and Cultures','locked'],['1.M','Unit 1 Mastery','locked']];
const scenes=[['Orient','A library, not a single modern book','Locate the Bible as a collection of writings produced across many centuries, communities, genres, and historical settings.'],['Read','1 Corinthians 15:1–5','Paul summarizes a tradition he says he received and passed on: Christ died, was buried, was raised, and appeared. First ask what kind of claim this is before asking whether you assent to it.'],['Explain','What Christians mean by gospel','The New Testament uses “gospel” as announcement before it becomes a label for four written works. That distinction matters when reading Paul and the evangelists.'],['Visualize','Setting changes meaning','Political power, patronage, geography, language, and Jewish–Greco-Roman interaction create the world in which texts were heard.'],['Compare','Text, interpretation, doctrine','The words on the page, a reader’s interpretation, and a church’s doctrinal conclusion are related but not identical.'],['Practice','Classify the claim','Distinguish textual observation from historical reconstruction and theological inference.'],['Reflect','What changed?','Record one assumption about the Bible that became more precise during this lesson.']];
const state={dir:localStorage.getItem('cs-proto-dir')||'a',page:location.hash.slice(1)||'home',scene:0,book:'Genesis',topic:'Covenant',order:['Call of Abram','Exodus','Wilderness','Promised Land'],answer:null};
const app=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]));
const dname=()=>state.dir==='a'?'Living Library':state.dir==='b'?'Scholarly Folio':'Scripture Atlas';
function head(title,kicker,sub=''){return `<div class="section-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2>${sub?`<p class="muted">${sub}</p>`:''}</div></div>`}
function home(){let hero=state.dir==='a'?'Enter the library. Follow the story.':state.dir==='b'?'Read with context. Think with clarity.':'See the story. Trace the connections.';let sub=state.dir==='a'?'A tactile library that remembers where you left off.':state.dir==='b'?'A focused study desk with the next meaningful action always clear.':'A navigable map of the Bible, course, and your growing connections.';return `<section class="hero"><div class="hero-main"><div class="eyebrow">Bible literacy for thoughtful adults</div><h1>${hero}</h1><p class="muted" style="max-width:62ch;font-size:18px">${sub}</p><div class="cta"><button class="btn" data-page="lesson">Continue Unit 1 · Lesson 2</button><button class="btn secondary" data-page="bible">Open the Bible</button></div></div><aside class="hero-side"><div class="eyebrow">Your learning state</div><div class="metric"><b>33%</b><span>Unit 1 progress</span></div><div class="metric"><b>1</b><span>lesson retained</span></div><div class="metric"><b>5</b><span>reviews due this week</span></div><div class="metric"><b>45</b><span>curated Topics</span></div></aside></section>${head('Your shelf remembers','Continue')}<section class="grid cols3"><article class="card"><div class="eyebrow">Course</div><h3>The Story and Its Setting</h3><p class="muted">Unit 1 · Lesson 2 · Scene 1 of 7</p><div class="progress"><span></span></div><div class="cta"><button class="btn" data-page="lesson">Resume lesson</button></div></article><article class="card"><div class="eyebrow">Practice</div><h3>Memory & Meaning</h3><p class="muted">5 review prompts selected from material due now.</p><div class="cta"><button class="btn secondary" data-page="practice">Start review</button></div></article><article class="card"><div class="eyebrow">Independent study</div><h3>Explore covenant</h3><p class="muted">Scripture, Topic relationships, course connections, and competing interpretations in one place.</p><div class="cta"><button class="btn secondary" data-page="topics">Open Topic</button></div></article></section>`}
function course(){let atlas=state.dir==='c'?`<div class="atlas">${['Story','Order','Groups','Chronology','Content','Themes','Verses'].map((x,i)=>`<div class="${i===0?'current':''}"><div class="eyebrow">Phase ${i+1}</div><strong>${x}</strong></div>`).join('')}</div>`:'';return `${head('The Story and Its Setting','Unit 1 · Learn','Understand the big picture before details: story, world, people, places, then retrieval and mastery.')}${atlas}<section class="panel"><div style="display:flex;gap:18px;align-items:center;justify-content:space-between;flex-wrap:wrap"><div><div class="eyebrow">Unit progress</div><h3>1 of 5 lessons complete</h3></div><div style="min-width:240px;flex:1;max-width:560px"><div class="progress"><span></span></div></div><b style="font:700 38px var(--serif)">33%</b></div></section>${head('Build context in layers','Learning path')}<section class="path">${lessons.map(([n,t,s])=>`<button class="${s}" ${s==='current'?'data-page="lesson"':''}><span class="badge">${n}</span><h3>${t}</h3><p class="small muted">${s==='complete'?'Retained':s==='current'?'Continue now':'Unlocks in sequence'}</p></button>`).join('')}</section>${head('Study beyond the lesson','Unit apparatus')}<section class="grid cols4"><article class="card"><h3>Timeline</h3><p class="muted">Locate people and events without pretending every biblical book is arranged chronologically.</p></article><article class="card"><h3>Maps</h3><p class="muted">Follow movements, empires, exile, travel, and regional context.</p></article><article class="card"><h3>Vocabulary</h3><p class="muted">Keep key terms precise without turning the lesson into a glossary wall.</p></article><article class="card"><h3>Sources</h3><p class="muted">See where historical, lexical, and interpretive claims come from.</p></article></section>`}
function lesson(){let [name,title,body]=scenes[state.scene];let challenge=state.scene===5?`<div class="challenge"><div class="eyebrow">Retrieval challenge</div><h3>Which statement is a historical reconstruction rather than a direct textual observation?</h3>${['Paul says he received and passed on a tradition.','Corinth was shaped by Roman patronage networks.','The passage names Cephas among those who saw Jesus.','Paul says Christ was buried.'].map((x,i)=>`<button class="choice ${state.answer===i?'selected':''}" data-choice="${i}">${String.fromCharCode(65+i)} · ${x}</button>`).join('')}<button class="btn" id="check-choice">Check answer</button>${state.answer===1?`<div class="feedback good"><strong>Correct.</strong> Patronage is reconstructed from historical evidence about Roman Corinth; the other statements are directly observable in the passage.</div>`:state.answer!==null?`<div class="feedback bad">Not quite. Look for the claim that depends on external historical evidence rather than words in the passage.</div>`:''}</div>`:'';let visual=state.scene===3?`<div class="grid cols3" style="margin-top:22px"><div class="card"><div class="eyebrow">Place</div><h3>Corinth</h3><p class="muted">Roman colony, port economy, stratified civic life.</p></div><div class="card"><div class="eyebrow">Social world</div><h3>Patronage</h3><p class="muted">Status and reciprocity shape how communal conflict is heard.</p></div><div class="card"><div class="eyebrow">Language</div><h3>Greek</h3><p class="muted">Terms carry semantic ranges that rarely map one-to-one into English.</p></div></div>`:'';return `${head('The Story and Its Setting','Unit 1 · Lesson 2',`Scene ${state.scene+1} of ${scenes.length} · ${name}`)}<section class="lesson"><aside class="lesson-nav panel"><div class="eyebrow">Scenes</div><div class="scene-list">${scenes.map((s,i)=>`<button class="${i===state.scene?'active':''}" data-scene="${i}">${i+1} · ${s[0]}</button>`).join('')}</div></aside><article class="scene"><div class="eyebrow">${name}</div><h2>${title}</h2><p style="font-size:20px;max-width:65ch">${body}</p>${state.scene===1?`<blockquote class="quote">“For I delivered to you as of first importance what I also received…” <span class="small">— 1 Corinthians 15:3</span></blockquote><p class="muted">The prototype intentionally separates the text from later interpretation. Production Scripture remains tied to the canonical corpus.</p>`:''}${visual}${challenge}<div class="scene-footer"><button class="btn secondary" id="prev-scene" ${state.scene===0?'disabled':''}>← Previous</button><span class="small muted">${state.scene+1}/${scenes.length}</span><button class="btn" id="next-scene">${state.scene===scenes.length-1?'Finish lesson':'Continue →'}</button></div></article><aside class="lesson-aside"><div class="fact"><div class="eyebrow">Key distinction</div><strong>Text ≠ interpretation ≠ doctrine</strong><p class="small muted">The lesson repeatedly labels which kind of claim you are seeing.</p></div><div class="fact"><div class="eyebrow">Ask Theologian</div><p class="small">“Why does historical setting matter if Scripture is inspired?”</p><button class="btn secondary" data-page="theologian">Ask in context</button></div><div class="fact"><div class="eyebrow">Personal study</div><p class="small muted">Notes and journal remain private and unscored.</p></div></aside></section>`}
function bible(){return `${head('The Bible','66-book library','Browse the canon as a library, then move into book profiles, chapters, maps, timelines, and study tools.')}<section class="bookshelf">${books.map(b=>`<button class="spine ${state.book===b?'active':''}" data-book="${b}">${b}</button>`).join('')}</section><section class="book-detail"><article class="panel"><div class="eyebrow">Selected book</div><h2>${state.book}</h2><p class="muted">${state.book==='Genesis'?'Origins, ancestors, covenant, blessing, conflict, and the beginning of Israel’s family story.':'Prototype book profile: literary form, historical questions, canonical placement, themes, and reading guidance would appear here.'}</p><div class="grid cols3" style="margin-top:18px"><div><span class="badge">Category</span><p>Biblical book</p></div><div><span class="badge">Canon</span><p>${['Matthew','John','Romans','Hebrews','James','Revelation'].includes(state.book)?'New Testament':'Old Testament'}</p></div><div><span class="badge">Study</span><p>Reader · Map · Timeline</p></div></div></article><aside class="panel"><div class="eyebrow">Open next</div><h3>Reading workspace</h3><p class="muted">Chapter text remains primary. Apparatus opens beside it rather than replacing it.</p><div class="cta"><button class="btn">Open chapter 1</button><button class="btn secondary" data-page="theologian">Ask about ${state.book}</button></div></aside></section>`}
function practice(){return `${head('Practice','Retention · due now','Practice is reinforcement, not a second curriculum. It selects what you are most likely to benefit from retrieving today.')}<section class="practice"><article class="practice-card"><div class="eyebrow">Ordering challenge</div><h2>Put the story sequence in order</h2><p class="muted">Use the arrows to reorder. Production can also support drag, touch, and keyboard equivalents.</p><div class="order-list">${state.order.map((x,i)=>`<div class="order-item"><strong>${i+1}</strong><span>${x}</span><button data-up="${i}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" ${i===state.order.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="btn" id="check-order">Check order</button><div id="order-feedback"></div></article><aside class="grid"><div class="panel"><div class="eyebrow">Retention</div><div class="orb">72%</div><p class="small muted">Current estimated retention for Unit 1 material.</p></div><div class="panel"><div class="eyebrow">Why this appeared</div><p class="small">A delayed retrieval interval is due. Correct retrieval pushes the next review farther out.</p><p class="small muted">1 → 3 → 7 → 14 → 30 → 60 days</p></div></aside></section>`}
function topicsPage(){return `${head('Topics','Curated reference · not scored','Explore questions and concepts without turning reference reading into course completion.')}<section class="topics">${topics.map(([t,d])=>`<button class="topic-card ${state.topic===t?'active':''}" data-topic="${t}"><span class="badge">${t==='Covenant'?'Biblical theology':'Topic'}</span><div><h3>${t}</h3><p class="muted">${d}</p></div><span class="small">Open reference →</span></button>`).join('')}</section><section class="panel" style="margin-top:14px"><div class="eyebrow">Selected topic</div><h2>${state.topic}</h2><div class="grid cols3"><div><h3>Scripture</h3><p class="muted">Key passages with context and relationship labels.</p></div><div><h3>Course links</h3><p class="muted">Lessons where the concept is introduced, compared, or practiced.</p></div><div><h3>Interpretive questions</h3><p class="muted">Where traditions agree, differ, or use the same evidence differently.</p></div></div><div class="cta"><button class="btn secondary" data-page="theologian">Ask Theologian about ${state.topic}</button></div></section>`}
function localAnswer(q){let x=q.toLowerCase();if(x.includes('romans'))return{label:'contested interpretation',headline:'Romans 1 should be read with distinctions between text, historical context, interpretation, and later doctrinal use.',body:'Paul’s argument in Romans 1:18–32 concerns idolatry, disordered desire, and Gentile humanity within a larger argument that culminates in universal accountability. Christian traditions disagree about how verses 26–27 map onto contemporary categories of sexual orientation and faithful same-sex relationships. Canonical Shelf should present the wording, ancient context, major interpretive arguments, and its own stated theological position separately rather than collapsing them into one claim.',sources:['Romans 1:18–32 · Scripture','Romans 2:1–3 · immediate argumentative context','Canonical Shelf interpretive policy · evidence discipline']};if(x.includes('covenant'))return{label:'biblical theology',headline:'Covenant is a relationship structured by promise, obligation, identity, and divine purpose.',body:'The Bible uses covenant language in several distinct settings rather than one flat formula. Noah, Abraham, Sinai, David, prophetic new-covenant hopes, and New Testament interpretation overlap but are not interchangeable. A strong answer traces both continuity and difference.',sources:['Genesis 9 · Noah','Genesis 15/17 · Abraham','Exodus 19–24 · Sinai','Jeremiah 31:31–34 · new covenant']};return{label:'prototype synthesis',headline:'A responsible answer begins by identifying what kind of claim the question is asking for.',body:`For “${q}”, the production Theologian would retrieve relevant Scripture, course material, Topics, Statement-of-Faith policy, historical/lexical evidence, and competing interpretations before generating a cited answer. This prototype demonstrates the interaction and evidence layout; it does not pretend that a live language model is connected.`,sources:['Canonical Shelf curriculum','Curated Topics','Statement of Faith / editorial policy']}}
function theologian(){return `${head('Theologian','Ask · compare · investigate','A real question surface, not the broken Guide control. The prototype accepts questions now; production would connect this UX to retrieval + bounded model synthesis.')}<section class="theology"><aside class="theo-pane"><div class="eyebrow">Ways to ask</div><h3>Start with the task</h3>${['What does Romans 1 mean?','Compare views of covenant.','Why does historical context matter?','Show the evidence for this interpretation.'].map(q=>`<button class="choice quick-q">${q}</button>`).join('')}<div class="source"><div class="eyebrow">Current context</div><p class="small">Unit 1 · Lesson 2</p><p class="small muted">The Story and Its Setting</p></div></aside><section class="theo-pane"><div class="eyebrow">Conversation</div><h2>Ask a theological or biblical question</h2><form class="ask" id="ask-form"><textarea name="question" id="question" placeholder="Example: What does Romans 1 mean, and why do Christians disagree about it?" required></textarea><button class="btn">Ask</button></form><div id="answer-space"><div class="answer"><span class="badge">Prototype mode</span><h3>This form is intentionally functional.</h3><p class="muted">Submit any question. The local prototype responder demonstrates the answer structure and evidence UX without pretending an LLM backend exists yet.</p></div></div></section><aside class="theo-pane"><div class="eyebrow">Evidence rail</div><h3>What an answer should expose</h3><div class="source"><strong>Text</strong><p class="small muted">What the passage actually says.</p></div><div class="source"><strong>Context</strong><p class="small muted">Historical and literary reconstruction.</p></div><div class="source"><strong>Interpretations</strong><p class="small muted">Responsible competing readings.</p></div><div class="source"><strong>Canonical Shelf position</strong><p class="small muted">Clearly labeled rather than smuggled into “the text says.”</p></div></aside></section>`}
function setDir(d){state.dir=d;localStorage.setItem('cs-proto-dir',d);document.body.className='dir-'+d;render()}
function setPage(p){state.page=p;location.hash=p;render();scrollTo({top:0,behavior:'smooth'})}
function render(){document.body.className='dir-'+state.dir;document.querySelectorAll('[data-dir]').forEach(b=>b.classList.toggle('active',b.dataset.dir===state.dir));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));document.querySelector('#prototype-tag').textContent=`Prototype ${state.dir.toUpperCase()} · ${dname()}`;app.innerHTML=({home,course,lesson,bible,practice,topics:topicsPage,theologian}[state.page]||home)();bind()}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>setPage(el.dataset.page));document.querySelectorAll('[data-scene]').forEach(el=>el.onclick=()=>{state.scene=+el.dataset.scene;render()});document.querySelectorAll('[data-book]').forEach(el=>el.onclick=()=>{state.book=el.dataset.book;render()});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{state.topic=el.dataset.topic;render()});document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{state.answer=+el.dataset.choice;render()});document.querySelector('#prev-scene')?.addEventListener('click',()=>{state.scene=Math.max(0,state.scene-1);render()});document.querySelector('#next-scene')?.addEventListener('click',()=>{if(state.scene<scenes.length-1){state.scene++;render()}else setPage('course')});document.querySelector('#check-choice')?.addEventListener('click',()=>{if(state.answer===null)state.answer=-1;render()});document.querySelectorAll('[data-up]').forEach(el=>el.onclick=()=>{let i=+el.dataset.up;[state.order[i-1],state.order[i]]=[state.order[i],state.order[i-1]];render()});document.querySelectorAll('[data-down]').forEach(el=>el.onclick=()=>{let i=+el.dataset.down;[state.order[i+1],state.order[i]]=[state.order[i],state.order[i+1]];render()});document.querySelector('#check-order')?.addEventListener('click',()=>{let ok=state.order.join('|')==='Call of Abram|Exodus|Wilderness|Promised Land';document.querySelector('#order-feedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'Correct — the sequence is retained. Try again after a delay to strengthen retrieval.':'Not yet. Reconstruct the narrative sequence rather than guessing from the labels.'}</div>`});document.querySelectorAll('.quick-q').forEach(el=>el.onclick=()=>{document.querySelector('#question').value=el.textContent;document.querySelector('#question').focus()});document.querySelector('#ask-form')?.addEventListener('submit',e=>{e.preventDefault();let q=new FormData(e.target).get('question').trim();let a=localAnswer(q);document.querySelector('#answer-space').innerHTML=`<article class="answer"><span class="badge">${esc(a.label)}</span><h3>${esc(a.headline)}</h3><p>${esc(a.body)}</p><div class="eyebrow" style="margin-top:18px">Evidence shown in prototype</div>${a.sources.map(s=>`<div class="source">${esc(s)}</div>`).join('')}<p class="small muted">Interaction prototype only. A production conversational answer requires the retrieval/model layer discussed separately.</p></article>`})}
document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>setDir(b.dataset.dir));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'home';render()});setDir(state.dir);setPage(state.page);